// independent state per key, advancing lazily to whatever tick it is asked
// about next.

export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity // BigInt
    this.refill = refill // BigInt
    this.per = per // BigInt
    this.capacityNumerator = capacity * per
    this.states = new Map() // key -> { numerator: BigInt, lastTick: BigInt }
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      this.states.set(key, { numerator: this.capacityNumerator, lastTick: tick })
      return
    }
    const delta = tick - state.lastTick
    if (delta > 0n) {
      let numerator = state.numerator + this.refill * delta
      if (numerator > this.capacityNumerator) numerator = this.capacityNumerator
      state.numerator = numerator
    }
    state.lastTick = tick
  }

  allowed(key) {
    const state = this.states.get(key)
    return state.numerator >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.numerator -= this.per
  }
}

