  constructor(limit, span) {
    this.limit = limit // BigInt
    this.span = span // BigInt
    this.states = new Map() // key -> BigInt[] of remembered ticks
  }

  advance(key, tick) {
    let ticks = this.states.get(key)
    if (ticks === undefined) {
      ticks = []
      this.states.set(key, ticks)
    }
    const threshold = tick - this.span
    let dropCount = 0
    while (dropCount < ticks.length && ticks[dropCount] <= threshold) dropCount++
    if (dropCount > 0) ticks.splice(0, dropCount)
  }

