{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-sonnet-vs-opus-t5/cell-6gmSgv/src/engine.js","content":"// Parses and executes a limiter file, producing either a replay log or a
// summary, depending on the requested mode.

import { isValidToken, parseUnsignedInt, AppError } from './validate.js'
import { TokenBucket, SlidingWindow } from './policies.js'

function fail(line, reason) {
  throw new AppError(`line ${line}: ${reason}`)
}

// Validates an unsigned integer field, returning its BigInt value or
// raising the standard "<field> must be an integer of at least <least>"
// error.
function requireInt(line, field, text, least) {
  const value = parseUnsignedInt(text)
  if (value === null || value < least) {
    fail(line, `${field} must be an integer of at least ${least}`)
  }
  return value
}

export function run(input, mode) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map() // name -> { kind, impl }
  const routes = [] // { prefix, policyNames: string[] }
  const routesByPrefix = new Map()
  let eventSeen = false
  let lastEventTick = null // BigInt

  const perKeyOrder = [] // keys in first-seen order
  const perKeyStats = new Map() // key -> { allowed, denied }
  const replayLines = []

  function statsFor(key) {
    let s = perKeyStats.get(key)
    if (s === undefined) {
      s = { allowed: 0n, denied: 0n }
      perKeyStats.set(key, s)
      perKeyOrder.push(key)
    }
    return s
  }

  function routeFor(key) {
    let best = null
    for (const route of routes) {
      if (key.startsWith(route.prefix)) {
        if (best === null || route.prefix.length > best.prefix.length) best = route
      }
    }
    return best
  }

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (eventSeen) fail(lineNo, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (tokens.length !== 5) fail(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capacityText, refillText, perText] = tokens
      if (!isValidToken(name)) fail(lineNo, `invalid policy name ${name}`)
      const capacity = requireInt(lineNo, 'capacity', capacityText, 1n)
      const refill = requireInt(lineNo, 'refill', refillText, 0n)
      const per = requireInt(lineNo, 'per', perText, 1n)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      policies.set(name, { kind: 'bucket', impl: new TokenBucket(capacity, refill, per) })
    } else if (directive === 'window') {
      if (tokens.length !== 4) fail(lineNo, 'expected window <name> <limit> <span>')
      const [, name, limitText, spanText] = tokens
      if (!isValidToken(name)) fail(lineNo, `invalid policy name ${name}`)
      const limit = requireInt(lineNo, 'limit', limitText, 0n)
      const span = requireInt(lineNo, 'span', spanText, 1n)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      policies.set(name, { kind: 'window', impl: new SlidingWindow(limit, span) })
    } else if (directive === 'route') {
      if (tokens.length < 3) fail(lineNo, 'expected route <prefix> <policy>...')
      const prefix = tokens[1]
      const policyNames = tokens.slice(2)
      if (!isValidToken(prefix)) fail(lineNo, `invalid route prefix ${prefix}`)
      for (const name of policyNames) {
        if (!policies.has(name)) fail(lineNo, `unknown policy ${name}`)
      }
      if (routesByPrefix.has(prefix)) fail(lineNo, `prefix ${prefix} is routed twice`)
      const route = { prefix, policyNames }
      routesByPrefix.set(prefix, route)
      routes.push(route)
    } else if (directive === 'event') {
      if (tokens.length !== 3) fail(lineNo, 'expected event <tick> <key>')
      const [, tickText, key] = tokens
      const tick = requireInt(lineNo, 'tick', tickText, 0n)
      if (!isValidToken(key)) fail(lineNo, `invalid key ${key}`)
      if (lastEventTick !== null && tick < lastEventTick) {
        fail(lineNo, `tick ${tick} is before tick ${lastEventTick}`)
      }
      lastEventTick = tick
      eventSeen = true

      const route = routeFor(key)
      const policyNames = route === null ? [] : route.policyNames
      const impls = policyNames.map((name) => policies.get(name))

      for (const p of impls) p.impl.advance(key, tick)

      let denyIndex = -1
      for (let j = 0; j < impls.length; j++) {
        if (!impls[j].impl.allowed(key)) {
          denyIndex = j
          break
        }
      }

      const stats = statsFor(key)
      if (denyIndex === -1) {
        for (const p of impls) {
          if (p.kind === 'bucket') p.impl.record(key)
          else p.impl.record(key, tick)
        }
        stats.allowed += 1n
        replayLines.push(`${tick} ${key} allow`)
      } else {
        stats.denied += 1n
        replayLines.push(`${tick} ${key} deny ${policyNames[denyIndex]}`)
      }
    } else {
      fail(lineNo, `unknown directive ${directive}`)
    }
  }

  if (mode === 'replay') {
    return replayLines.length === 0 ? '' : replayLines.join('\n') + '\n'
  }

  // summary
  const keys = [...perKeyOrder].sort()
  const out = []
  let totalAllowed = 0n
  let totalDenied = 0n
  for (const key of keys) {
    const s = perKeyStats.get(key)
    out.push(`${key} allowed=${s.allowed} denied=${s.denied}`)
    totalAllowed += s.allowed
    totalDenied += s.denied
  }
  out.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  return out.join('\n') + '\n'
}
